predicted_sql:
SELECT School, EILName
FROM schools
WHERE CDSCode = '01612590136051';

SELECT ROUND(
    100.0 * COUNT(DISTINCT fd.uuid) / (SELECT COUNT(*) FROM cards),
    2
) AS percentage
FROM foreign_data AS fd
WHERE fd.language = 'Chinese Simplified';

SELECT DISTINCT text
FROM cards
WHERE name = 'Benalish Knight';

SELECT COUNT(DISTINCT name) AS number_of_cards
FROM cards
WHERE ',' || promoTypes || ',' LIKE '%,release,%';

SELECT ROUND(
    100.0 * SUM(CASE WHEN Tags LIKE '%<r>%' THEN 1 ELSE 0 END) / COUNT(*),
    2
)
FROM posts
WHERE OwnerUserId = -1;

SELECT ROUND(
    100.0 * SUM(
        CASE WHEN NOT EXISTS (
            SELECT 1
            FROM "member" AS m
            WHERE m.link_to_major = major.major_id
        ) THEN 1 ELSE 0 END
    ) / COUNT(*),
    2
) AS percentage_unrepresented_majors
FROM major;

SELECT COUNT(DISTINCT ID)
FROM Patient
WHERE lower(Diagnosis) LIKE '%psoriatic arthritis%';

SELECT ROUND(
    100.0 * SUM(CASE WHEN LOWER(element) = 'cl' THEN 1 ELSE 0 END) / COUNT(*),
    4
)
FROM atom
WHERE molecule_id IN (
    SELECT molecule_id
    FROM bond
    WHERE bond_type = '-'
);

SELECT ROUND(
    1.0 * (SELECT COUNT(*) FROM bond WHERE molecule_id = 'TR397') /
    (SELECT COUNT(*) FROM atom WHERE molecule_id = 'TR397'),
    2
) AS average_bonds_per_atom;
